import re,glob,collections
rows=[];bad=[]
for f in sorted(glob.glob('*.txt')):
    t=open(f).read()
    for pg in re.split(r'=== page \d+',t)[1:]:
        m=re.search(r'finds the following\s+violation\(s\):(.*?)The Advisory Committee recommends',pg,re.S)
        if not m: 
            if 'finds the following' in pg: bad.append((f,pg[:200]))
            continue
        cite=' '.join(m.group(1).split())
